const cache = {};

app.get('/api/trending-movies', async (req, res) => {
  // 1. Check if we have the data in memory and if it is less than 5 minutes old
  if (cache.movies && cache.timestamp > Date.now() - 300000) {
    return res.status(200).json(cache.movies); // INSTANT RESPONSE
